119	      id: i.id,
120	      colors: i.colors ?? [],
121	      category: i.category,
122	      formality: i.formality,
123	      seasons: i.seasons ?? [],
124	      material: i.material,
125	    }));
126	
127	    const args = {
128	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
129	      season: currentSeason(now),
130	      excludeItemIds: [],
131	      maxAccessories: 1,
132	    };
