134	
135	    // Try the day's own formality band first, then the full scale. A piece
136	    // dressier or more casual than today's context is still stylable — refusing
137	    // would be the "hard filter empties a required slot" trap again.
138	    let pinned: ReturnType<typeof rankTopN> = [];
139	    for (const band of [personalBand(occasion, profile), [1, 5] as [number, number]]) {
140	      const combos = buildCandidates(candItems, { ...args, band });
141	      const ranked = rankTopN(
142	        combos,
143	        { aesthetic, band, lean: [], recentlyShown: [], season: args.season },
