157	    const byId = new Map(items.map((i) => [i.id, i]));
158	    const shortlist = pinned.slice(0, 20);
159	
160	    const { picks } = await rerank({
161	      want: 1,
162	      combos: shortlist.map((t) =>
163	        t.items.map((ci) => {
164	          const it = byId.get(ci.id)!;
165	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
166	        }),
167	      ),
168	      aesthetic,
169	      occasion,
170	      weatherLabel: f.condition,
171	      tempC: f.tempC,
172	    });
173	
174	    const chosen = shortlist[picks[0]?.combo_index ?? 0] ?? shortlist[0];
175	    const dbItems = chosen.items.map((ci) => byId.get(ci.id)!);
176	    const paths = dbItems.map(displayPath);
177	    const signed = await signItemImages(paths);
178	    const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
179	    const pieces: LookPiece[] = dbItems.map((d, idx) => ({
180	      itemId: d.id,
181	      category: d.category,
182	      subcategory: d.subcategory ?? null,
183	      brand: d.brand ?? null,
184	      name: d.name ?? null,
185	      colors: d.colors ?? [],
186	      cutoutUrl: signed.get(displayPath(d)) ?? "",
187	      slot: slots[idx],
188	    }));
189	
190	    const draft: LookDraft = {
191	      name: picks[0]?.name || styledLookName(subject),
192	      why: picks[0]?.why ?? "",
193	      pieces,
194	      anchorIndex: staggerOrder(slots)[0],
195	    };
196	
197	    const outfitId = await saveStyledLook(user.id, itemId, occasion, today, weather, draft);
198	    if (!outfitId) return { status: "error", message: "Couldn't save the look" };
199	
200	    return { status: "ok", outfitId };
201	  } catch (e) {
202	    console.error("[styleWithItem] failed:", e);
203	    return { status: "error", message: e instanceof Error ? e.message : "Couldn't style this" };
204	  }
205	}
