6	/** Today's stored set for one occasion, in the order the stylist chose. */
7	export async function loadDailyLooks(
8	  userId: string,
9	  occasion: string,
10	  generatedOn: string,
11	): Promise<StoredLook[] | null> {
12	  const supabase = await createClient();
13	  const { data } = await supabase
14	    .from("outfits")
15	    // `wear_logs(worn_on)` is the reverse of wear_logs.outfit_id. A look the
16	    // user has already worn today stays in the set and is badged, rather than
17	    // disappearing the moment they tap the button.
18	    .select("id, look_name, ai_reasoning, layout, look_index, wear_logs(worn_on)")
19	    .eq("user_id", userId)
20	    .eq("occasion", occasion)
21	    .eq("generated_on", generatedOn)
22	    // A "Style an outfit with this" look is dated and carries an occasion too,
23	    // so it matches this filter — without the guard it shows up as an extra
24	    // look in the day's set.
25	    .is("styled_item_id", null)
26	    .order("look_index", { ascending: true });
27	
28	  if (!data || data.length === 0) return null;
29	
30	  return data.map((row) => {
31	    const layout = (row.layout ?? {}) as {
32	      anchorIndex?: number;
33	      pieces?: StoredLook["pieces"];
34	    };
35	    return {
36	      id: row.id,
37	      lookName: row.look_name ?? "",
38	      why: row.ai_reasoning ?? "",
39	      anchorIndex: layout.anchorIndex ?? 0,
40	      pieces: layout.pieces ?? [],
41	      worn: isWornToday(row.wear_logs ?? [], generatedOn),
42	    };
43	  });
44	}
