46	/**
47	 * Replace today's set for one occasion. Delete-then-insert rather than upsert:
48	 * a regenerate may return a different NUMBER of looks, and leftovers from the
49	 * previous set must not survive alongside the new one.
50	 *
51	 * One exception, and it is the reason this function can be called at all after
52	 * a wear: an outfit with a wear log is PINNED. `wear_logs.outfit_id` used to
53	 * have no ON DELETE action, so deleting a worn outfit raised a foreign-key
54	 * violation and the whole regeneration failed. Pinning is also the honest
55	 * product behaviour — what you actually wore today is not a suggestion to be
56	 * thrown away, so it keeps its place in the day's set and the fresh looks are
57	 * numbered past it (`outfits_daily_unique` covers `look_index`).
58	 *
59	 * Returns the new outfit ids, aligned with the `looks` array.
60	 */
61	export async function saveDailyLooks(
62	  userId: string,
63	  occasion: string,
64	  generatedOn: string,
65	  weather: WeatherPayload,
66	  looks: LookDraft[],
67	): Promise<string[]> {
68	  const supabase = await createClient();
69	
70	  const { data: existing } = await supabase
71	    .from("outfits")
72	    .select("id, look_index, wear_logs(worn_on)")
73	    .eq("user_id", userId)
74	    .eq("occasion", occasion)
75	    .eq("generated_on", generatedOn)
76	    .is("styled_item_id", null);
77	
78	  // Any wear log pins the row — not just today's. The point is that nothing
79	  // referenced by wear_logs is ever deleted here.
80	  const pinned = (existing ?? []).filter((r) => (r.wear_logs ?? []).length > 0);
81	
82	  let del = supabase
83	    .from("outfits")
84	    .delete()
85	    .eq("user_id", userId)
86	    .eq("occasion", occasion)
87	    .eq("generated_on", generatedOn)
88	    // Never delete a styled look: it is a cached answer to a different
89	    // question, and a regenerate has no business invalidating it.
90	    .is("styled_item_id", null);
91	  if (pinned.length) del = del.not("id", "in", `(${pinned.map((r) => r.id).join(",")})`);
92	  await del;
93	
94	  const start = freshIndexStart(pinned.map((r) => r.look_index));
95	  const rows = looks.map((look, i) => ({
96	    user_id: userId,
97	    occasion,
98	    generated_on: generatedOn,
99	    look_index: start + i,
100	    look_name: look.name,
101	    ai_reasoning: look.why,
102	    weather_snapshot: weather,
103	    layout: {
104	      anchorIndex: look.anchorIndex,
105	      pieces: look.pieces.map((p) => ({ itemId: p.itemId, slot: p.slot })),
106	    },
107	  }));
108	
109	  const { data: inserted } = await supabase
110	    .from("outfits")
111	    .insert(rows)
112	    .select("id, look_index");
113	  if (!inserted) return [];
114	
115	  // outfit_items is the relational record — it is what wear_logs and future
116	  // analytics join against. The renderable geometry lives in outfits.layout.
117	  const links = inserted.flatMap((row) => {
118	    const look = looks[row.look_index - start];
119	    return (look?.pieces ?? []).map((p) => ({
120	      outfit_id: row.id,
121	      item_id: p.itemId,
122	      slot: p.category,
123	    }));
124	  });
125	  if (links.length) await supabase.from("outfit_items").insert(links);
126	
127	  // Insert order is not guaranteed — place each id at its look's position.
128	  const ids: string[] = [];
129	  for (const row of inserted) ids[row.look_index - start] = row.id;
130	  return ids;
131	}
