11	export default async function ItemPage({
12	  params,
13	}: {
14	  params: Promise<{ itemId: string }>;
15	}) {
16	  const { itemId } = await params;
17	  const supabase = await createClient();
18	  const {
19	    data: { user },
20	  } = await supabase.auth.getUser();
21	  if (!user) redirect("/");
22	
23	  const { data: item } = await supabase.from("items").select("*").eq("id", itemId).single();
24	  if (!item) notFound();
25	
26	  // The rest of the wardrobe — used for "Goes with" and the brand suggestions.
27	  const { data: closetRows } = await supabase.from("items").select("*").eq("archived", false);
28	  const closet = closetRows ?? [];
29	
30	  /**
31	   * Wear history for ONE item.
32	   *
33	   * A wear is logged against an OUTFIT, never an item, so an item's wear count
34	   * is "how many logged outfits contained it": wear_logs → outfit_items. The
35	   * `!inner` is what makes the embed a restriction rather than a nullable join —
36	   * without it every wear log in the account comes back and every item claims
37	   * the same wear count.
