39	  const { data: logs } = await supabase
40	    .from("wear_logs")
41	    .select("worn_on, outfit_items!inner(item_id)")
42	    .eq("outfit_items.item_id", itemId);
43	
44	  const { data: profile } = await supabase
45	    .from("profiles")
46	    .select("location_timezone")
47	    .eq("id", user.id)
48	    .single();
