57	      category: i.category,
58	      colors: i.colors ?? [],
59	      formality: i.formality,
60	    })),
61	  );
62	  const byId = new Map(closet.map((i) => [i.id, i]));
63	  const pairs = pairIds.flatMap((id) => {
64	    const row = byId.get(id);
65	    return row ? [row] : [];
66	  });
67	
68	  const signed = await signItemImages([item, ...pairs].map(displayPath));
69	
70	  const goesWithCards: GoesWithCard[] = pairs.map((i) => ({
71	    id: i.id,
