7	/**
8	 * Log or unlog "I wore this today".
9	 *
10	 * This writes to wear_logs and nothing else — the outfit row is left alone on
11	 * purpose. A worn look stays in today's set, badged rather than removed, and
12	 * `saveDailyLooks` is what protects it from a later Regenerate by excluding
13	 * anything with a wear log from the day's delete. (That delete is also why the
14	 * FK used to matter: it had no ON DELETE action, so regenerating after a wear
15	 * raised a foreign-key violation.)
16	 *
17	 * Unlogging therefore just clears the badge. Nothing else about the day moves.
18	 */
19	export async function toggleWear(outfitId: string): Promise<{ worn: boolean }> {
20	  const supabase = await createClient();
21	  const {
22	    data: { user },
23	  } = await supabase.auth.getUser();
24	  if (!user) throw new Error("Not signed in");
25	
26	  // The user's LOCAL date. `localDateFor` REQUIRES a timezone — there is no
27	  // zero-argument variant, and defaulting to UTC would move an evening wear in
28	  // Berlin onto the next day, which is exactly the bug this avoids. The zone
29	  // lives on the profile, written by the location work.
30	  const { data: profile } = await supabase
31	    .from("profiles")
32	    .select("location_timezone")
33	    .eq("id", user.id)
34	    .single();
35	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
36	
37	  // RLS scopes every statement below to the owner; a foreign id matches 0 rows.
38	  const { data: existing } = await supabase
39	    .from("wear_logs")
40	    .select("id")
41	    .eq("outfit_id", outfitId)
42	    .eq("worn_on", today)
43	    .maybeSingle();
44	
45	  if (existing) {
46	    const { error } = await supabase.from("wear_logs").delete().eq("id", existing.id);
47	    if (error) throw new Error(error.message);
48	    revalidatePath(`/outfits/${outfitId}`);
49	    revalidatePath("/generate");
50	    return { worn: false };
51	  }
52	
53	  const { data: outfit } = await supabase
54	    .from("outfits")
55	    .select("occasion")
56	    .eq("id", outfitId)
57	    .single();
58	
59	  const { error } = await supabase.from("wear_logs").insert({
60	    user_id: user.id,
61	    outfit_id: outfitId,
62	    worn_on: today,
63	    occasion: outfit?.occasion ?? null,
64	  });
65	  if (error) throw new Error(error.message);
66	
67	  revalidatePath(`/outfits/${outfitId}`);
68	  revalidatePath("/generate");
69	  return { worn: true };
70	}
